{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.qc_inventory AS WITH inventory_raw AS ( SELECT \'KNOT\' AS marketplace, i.style AS sku_style, i.size AS sku_size, COALESCE( SAFE_CAST(CAST(i.Updated_Date AS STRING) AS DATE), DATE(SAFE_CAST(CAST(i.Updated_Date AS STRING) AS TIMESTAMP)), SAFE.PARSE_DATE(\'%d-%m-%Y\', CAST(i.Updated_Date AS STRING)), DATE_ADD( DATE \'1899-12-30\', INTERVAL SAFE_CAST( SAFE_CAST(CAST(i.Updated_Date AS STRING) AS FLOAT64) AS INT64 ) DAY ) ) AS inventory_date, IFNULL(CAST(i.inventory AS INT64), 0) AS inventory FROM maplemonk.QC_Knot_inventory i UNION ALL SELECT \'NEON MARKET\' AS marketplace, i.style AS sku_style, i.size AS sku_size, COALESCE( SAFE_CAST(CAST(i.Updated_Date AS STRING) AS DATE), DATE(SAFE_CAST(CAST(i.Updated_Date AS STRING) AS TIMESTAMP)), SAFE.PARSE_DATE(\'%d-%m-%Y\', CAST(i.Updated_Date AS STRING)), DATE_ADD( DATE \'1899-12-30\', INTERVAL SAFE_CAST( SAFE_CAST(CAST(i.Updated_Date AS STRING) AS FLOAT64) AS INT64 ) DAY ) ) AS inventory_date, IFNULL(CAST(i.inventory AS INT64), 0) AS inventory FROM maplemonk.GS_Neon_Market_inventory i UNION ALL SELECT \'SLIKK\' AS marketplace, i.style AS sku_style, i.size AS sku_size, COALESCE( SAFE_CAST(CAST(i.Updated AS STRING) AS DATE), DATE(SAFE_CAST(CAST(i.Updated AS STRING) AS TIMESTAMP)), SAFE.PARSE_DATE(\'%d-%m-%Y\', CAST(i.Updated AS STRING)), DATE_ADD( DATE \'1899-12-30\', INTERVAL SAFE_CAST( SAFE_CAST(CAST(i.Updated AS STRING) AS FLOAT64) AS INT64 ) DAY ) ) AS inventory_date, IFNULL(CAST(i.inventory AS INT64), 0) AS inventory FROM maplemonk.QC_Slikk_inventory i ), deduplicated AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY marketplace, sku_style, sku_size, inventory_date ORDER BY inventory_date DESC ) AS rw FROM inventory_raw ) SELECT * FROM deduplicated WHERE rw = 1; CREATE OR REPLACE TABLE maplemonk.quick_com_inv_sales AS WITH inventory AS ( SELECT * FROM maplemonk.qc_inventory QUALIFY ROW_NUMBER() OVER ( PARTITION BY marketplace, sku_style, sku_size ORDER BY inventory_date DESC ) = 1 ), sales AS ( SELECT LOWER(TRIM(s.sku_style)) AS style, LOWER(TRIM(s.sku_size)) AS size, CASE WHEN LOWER(s.marketplace) LIKE \'%knot%\' THEN \'KNOT\' WHEN LOWER(s.marketplace) LIKE \'%neon%\' THEN \'NEON MARKET\' WHEN LOWER(s.marketplace) LIKE \'%slikk%\' THEN \'SLIKK\' END AS marketplace, DATE(s.order_date) AS order_date, SUM(IFNULL(s.quantity, 0)) AS quantity FROM maplemonk.izf_sales_consolidated s WHERE LOWER(s.marketplace) LIKE \'%knot%\' OR LOWER(s.marketplace) LIKE \'%neon%\' OR LOWER(s.marketplace) LIKE \'%slikk%\' GROUP BY 1, 2, 3, 4 ), aggregated_sales AS ( SELECT i.marketplace, i.sku_style, i.sku_size, MAX(i.inventory_date) AS inventory_date, SUM(s.quantity) AS sold_quantity FROM sales s LEFT JOIN inventory i ON s.style = LOWER(TRIM(i.sku_style)) AND s.size = LOWER(TRIM(i.sku_size)) AND s.marketplace = i.marketplace AND s.order_date >= i.inventory_date GROUP BY 1, 2, 3 ) SELECT i.marketplace, i.sku_style, i.sku_size, i.inventory_date, i.inventory, IFNULL(s.sold_quantity, 0) AS sold_quantity_since_update FROM inventory i LEFT JOIN aggregated_sales s ON i.sku_style = s.sku_style AND i.sku_size = s.sku_size AND i.marketplace = s.marketplace AND i.inventory_date = s.inventory_date;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            